create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text not null, full_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.companies (id uuid primary key default gen_random_uuid(), name text not null, country text not null, industry text not null, website text, default_currency text not null default 'USD', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.company_members (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null default 'owner' check (role in ('owner','admin','sales','viewer')), created_at timestamptz not null default now(), unique(company_id, user_id));
create table public.product_imports (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, filename text not null, status text not null, total_rows integer not null default 0, imported_rows integer not null default 0, failed_rows integer not null default 0, mapping jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), completed_at timestamptz);
create table public.products (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, sku text not null, name text not null, description text, category text, model text, material text, size text, specifications jsonb not null default '{}'::jsonb, cost numeric, currency text not null default 'USD', moq integer, lead_time_days integer, unit text, active boolean not null default true, source_import_id uuid references public.product_imports(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id, sku));
create table public.documents (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, storage_path text not null, original_filename text not null, mime_type text not null, size_bytes bigint not null, document_type text not null check (document_type in ('product_catalog','rfq','quotation','other')), created_at timestamptz not null default now());
create or replace function public.is_company_member(target_company_id uuid) returns boolean language sql stable security invoker set search_path = public as $$ select exists (select 1 from public.company_members where company_id = target_company_id and user_id = (select auth.uid())); $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security invoker set search_path = public as $$ begin insert into public.profiles (id, email) values (new.id, new.email); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create schema if not exists private;
create or replace function private.handle_new_company_owner() returns trigger language plpgsql security definer set search_path = public, private as $$ begin if (select auth.uid()) is null then raise exception 'Authentication required'; end if; insert into public.company_members (company_id, user_id, role) values (new.id, (select auth.uid()), 'owner'); return new; end; $$;
revoke all on function private.handle_new_company_owner() from public;
create trigger on_company_created after insert on public.companies for each row execute procedure private.handle_new_company_owner();
alter table public.profiles enable row level security; alter table public.companies enable row level security; alter table public.company_members enable row level security; alter table public.products enable row level security; alter table public.product_imports enable row level security; alter table public.documents enable row level security;
create policy "Users read own profile" on public.profiles for select to authenticated using (id = (select auth.uid()));
create policy "Users update own profile" on public.profiles for update to authenticated using (id = (select auth.uid())) with check (id = (select auth.uid()));
create policy "Members read own companies" on public.companies for select to authenticated using (public.is_company_member(id));
create policy "Authenticated users create companies" on public.companies for insert to authenticated with check (true);
create policy "Members update own companies" on public.companies for update to authenticated using (public.is_company_member(id)) with check (public.is_company_member(id));
create policy "Users read own memberships" on public.company_members for select to authenticated using (user_id = (select auth.uid()));
create policy "Members read products" on public.products for select to authenticated using (public.is_company_member(company_id));
create policy "Members insert products" on public.products for insert to authenticated with check (public.is_company_member(company_id));
create policy "Members update products" on public.products for update to authenticated using (public.is_company_member(company_id)) with check (public.is_company_member(company_id));
create policy "Members delete products" on public.products for delete to authenticated using (public.is_company_member(company_id));
create policy "Members read imports" on public.product_imports for select to authenticated using (public.is_company_member(company_id));
create policy "Members create imports" on public.product_imports for insert to authenticated with check (public.is_company_member(company_id));
create policy "Members read documents" on public.documents for select to authenticated using (public.is_company_member(company_id));
create policy "Members create documents" on public.documents for insert to authenticated with check (public.is_company_member(company_id));
insert into storage.buckets (id, name, public) values ('company-documents', 'company-documents', false) on conflict (id) do nothing;
create policy "Members upload company documents" on storage.objects for insert to authenticated with check (bucket_id = 'company-documents' and public.is_company_member((storage.foldername(name))[1]::uuid));
create policy "Members read company documents" on storage.objects for select to authenticated using (bucket_id = 'company-documents' and public.is_company_member((storage.foldername(name))[1]::uuid));
create policy "Members update company documents" on storage.objects for update to authenticated using (bucket_id = 'company-documents' and public.is_company_member((storage.foldername(name))[1]::uuid)) with check (bucket_id = 'company-documents' and public.is_company_member((storage.foldername(name))[1]::uuid));
